class Solution {
    private int count = 0;
    public int totalNQueens(int n) {
        solve(0, n, new boolean[n], new boolean[2 * n], new boolean[2 * n]);
        return count;
    }
    private void solve(int row, int n, boolean[] cols, boolean[] d1, boolean[] d2) {
        if (row == n) { count++; return; }
        for (int col = 0; col < n; col++) {
            if (!cols[col] && !d1[row - col + n] && !d2[row + col]) {
                cols[col] = d1[row - col + n] = d2[row + col] = true;
                solve(row + 1, n, cols, d1, d2);
                cols[col] = d1[row - col + n] = d2[row + col] = false;
            }
        }
    }
}

class Solution {
    private int count;
    public int totalNQueens(int n) {
        count = 0;
        solve(0, n, 0, 0, 0);
        return count;
    }
    private void solve(int row, int n, int colMask, int d1Mask, int d2Mask) {
        if (row == n) {
            count++;
            return;
        }
        int available = ((1 << n) - 1) & ~(colMask | d1Mask | d2Mask);
        while (available != 0) {
            int bit = available & (-available);
            available &= available - 1;
            solve(row + 1, n, colMask | bit, (d1Mask | bit) << 1, (d2Mask | bit) >>> 1);
        }
    }
}
